import pathlib

import click
import yaml

from tidewater.ingest import csv_drop, noaa
from tidewater.load import warehouse


@click.group()
def main():
    """tidewater pipeline commands."""


@main.group()
def stations():
    pass


@stations.command("list")
@click.option("--config", default="config/stations.yaml")
def stations_list(config):
    data = yaml.safe_load(open(config))
    for s in data["stations"]:
        click.echo(f"{s['id']}\t{s['name']}\t{s['source']}\t{s.get('datum', '')}")


@main.command()
@click.option("--dir", "mig_dir", default="migrations")
def migrate(mig_dir):
    conn = warehouse.connect()
    for path in sorted(pathlib.Path(mig_dir).glob("*.sql")):
        warehouse.apply_migration(conn, path)
        click.echo(f"applied {path.name}")


@main.command()
@click.option("--config", default="config/pipeline.toml")
@click.option("--station", multiple=True)
@click.option("--since", type=click.DateTime(formats=["%Y-%m-%d"]), default=None)
@click.option("--min-level-mm", type=int, default=-9000, help="readings below this are dropped")
def backfill(config, station, since, min_level_mm):
    cfg = warehouse.load_config(config)
    conn = warehouse.connect(cfg["warehouse"]["url"])
    begin = since.strftime("%Y%m%d") if since else None
    for sid in station:
        readings = noaa.fetch_range(sid, cfg, begin=begin)
        readings = [r for r in readings if r.level_mm >= min_level_mm]
        warehouse.write_readings(conn, readings)


if __name__ == "__main__":
    main()

"""Write readings to TimescaleDB."""
import tomllib

import psycopg

DEFAULT_URL = "postgresql://tide:tide@localhost:5433/tide"


def load_config(path):
    with open(path, "rb") as fh:
        return tomllib.load(fh)


def connect(url=DEFAULT_URL):
    return psycopg.connect(url, autocommit=True)


def apply_migration(conn, path):
    conn.execute(open(path).read())


def write_readings(conn, readings):
    with conn.cursor() as cur:
        cur.executemany(
            "INSERT INTO readings (station_id, observed_at, level_mm, sigma_mm, source, qc_flags, battery_mv)"
            " VALUES (%s, to_timestamp(%s), %s, %s, %s, %s, %s)"
            " ON CONFLICT (station_id, observed_at) DO NOTHING",
            [
                (r.station_id, r.observed_at, r.level_mm, r.sigma_mm, r.source, r.qc_flags,
                 r.battery_mv)
                for r in readings
            ],
        )

